/* @lc app=leetcode id=2781 lang=kotlin */ class Solution { fun longestValidSubstring(word: String, forbidden: List<String>): Int = forbidden.toSet().let { fb -> word.indices.fold(0 to 0) { (l, best), j -> (1..minOf(10, j - l + 1)).firstOrNull { k -> word.substring(j - k + 1, j + 1) in fb }.let { k -> (if (k == null) l else j - k + 2).let { nl -> nl to maxOf(best, j - nl + 1) } } }.second } }